using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class StylizedHeroVisual:MonoBehaviour
{
private HeroIdentity identity;private TeamMember team;private bool built;private void Start(){Build();}public void Build(){if(built)return;identity=GetComponent<HeroIdentity>();team=GetComponent<TeamMember>();if(identity==null)return;built=true;Color accent=StylizedArtDirection.HeroAccent(identity.Hero);Color teamEdge=team!=null&&team.Team==1?StylizedArtDirection.LumenEnergy:StylizedArtDirection.ZeroEnergy;CreatePart("DF_Head",PrimitiveType.Sphere,new Vector3(0,.82f,0),new Vector3(.62f,.52f,.62f),accent);switch(identity.Hero){case HeroId.Kaelon:CreatePart("DF_ShoulderL",PrimitiveType.Cube,new Vector3(-.58f,.34f,0),new Vector3(.48f,.28f,.68f),accent);CreatePart("DF_ShoulderR",PrimitiveType.Cube,new Vector3(.58f,.34f,0),new Vector3(.48f,.28f,.68f),accent);break;case HeroId.Nyra:CreatePart("DF_Rifle",PrimitiveType.Cube,new Vector3(.55f,.18f,.42f),new Vector3(.12f,.12f,1.25f),accent);break;case HeroId.Elyra:CreatePart("DF_Orbit",PrimitiveType.Sphere,new Vector3(.62f,.5f,0),Vector3.one*.22f,accent);break;case HeroId.Mira:CreatePart("DF_Wings",PrimitiveType.Cube,new Vector3(0,.32f,-.28f),new Vector3(1.25f,.12f,.38f),accent);break;case HeroId.Rook:CreatePart("DF_Gauntlet",PrimitiveType.Cube,new Vector3(.58f,.08f,.2f),new Vector3(.48f,.48f,.62f),accent);break;default:CreatePart("DF_Blade",PrimitiveType.Cube,new Vector3(.52f,.12f,.28f),new Vector3(.12f,.85f,.14f),accent);break;}CreatePart("DF_TeamMark",PrimitiveType.Cube,new Vector3(0,1.18f,0),new Vector3(.38f,.06f,.38f),teamEdge);}
private void CreatePart(string n,PrimitiveType type,Vector3 pos,Vector3 scale,Color color){GameObject p=GameObject.CreatePrimitive(type);p.name=n;p.transform.SetParent(transform,false);p.transform.localPosition=pos;p.transform.localScale=scale;Collider c=p.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=p.GetComponent<Renderer>();if(r!=null)r.material.color=color;}
}
}
